function add(slug,q=1,pot){const p=byslug(slug);pot=pot||p.defPot||'goni';const l=S.cart.find(x=>x.s===slug&&x.pot===pot);if(l)l.q+=q;else S.cart.push({s:slug,q,pot});save();toast(`${nm(p)} · ${t('added').toLowerCase()}`,{t:t('cart'),run:openCart})}
function badge(){$$('.cartn').forEach(b=>{b.textContent=count();b.hidden=!count()})}
