function bindCards(root=document){$$('[data-add]',root).forEach(b=>b.onclick=e=>{e.preventDefault();add(b.dataset.add);b.classList.add('ok');b.innerHTML=ic('check');setTimeout(()=>{b.classList.remove('ok');b.innerHTML=ic('plus')},1300)})}

